import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"File not found: {script_path}")
    result = None
    timed_out = False
    def run_script():
        nonlocal result
        try:
            result = subprocess.run(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
        except subprocess.TimeoutExpired:
            timed_out = True
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        timed_out = True
        thread.join()
    if timed_out:
        return "Terminating process due to timeout."
    else:
        return "Script executed successfully."

